// Package fifo implements a fixed-size FIFO (First-In-First-Out) list data structure
// using a singly-linked list. The implementation prioritizes storage efficiency by minimizing
// storage operations - each add/remove operation only updates 1-2 pointers, regardless of
// list size.
//
// Key features:
// - Fixed-size with automatic removal of oldest entries when full
// - Support for both prepend (add at start) and append (add at end) operations
// - Constant storage usage through automatic pruning
// - O(1) append operations and latest element access
// - Iterator support for sequential access
// - Dynamic size adjustment via SetMaxSize
//
// This implementation is optimized for frequent updates, as insertions and deletions only
// require updating 1-2 pointers. However, random access operations are O(n) as they require
// traversing the list. For use cases where writes are rare, a slice-based
// implementation might be more suitable.
//
// The linked list structure is equally efficient for storing both small values (like pointers)
// and larger data structures, as each node maintains a single next-pointer regardless of the
// stored value's size.
//
// Example usage:
//
//	list := fifo.New(3)        // Create a new list with max size 3
//	list.Append("a")           // List: [a]
//	list.Append("b")           // List: [a b]
//	list.Append("c")           // List: [a b c]
//	list.Append("d")           // List: [b c d] (oldest element "a" was removed)
//	latest := list.Latest()    // Returns "d"
//	all := list.Entries()      // Returns ["b", "c", "d"]
package fifo

// node represents a single element in the linked list
type node struct {
	value any
	next  *node
}

// List represents a fixed-size FIFO list
type List struct {
	head    *node
	tail    *node
	size    int
	maxSize int
}

// New creates a new FIFO list with the specified maximum size
func New(maxSize int) *List {
	return &List{
		maxSize: maxSize,
	}
}

// Prepend adds a new entry at the start of the list. If the list exceeds maxSize,
// the last entry is automatically removed.
func (l *List) Prepend(entry any) {
	if l.maxSize == 0 {
		return
	}

	newNode := &node{value: entry}

	if l.head == nil {
		l.head = newNode
		l.tail = newNode
		l.size = 1
		return
	}

	newNode.next = l.head
	l.head = newNode

	if l.size < l.maxSize {
		l.size++
		return
	}

	// Remove last element by traversing to second-to-last
	if l.size == 1 {
		// Special case: if size is 1, just update both pointers
		l.head = newNode
		l.tail = newNode
		newNode.next = nil
		return

	}

	// Find second-to-last node
	current := l.head
	for current.next != l.tail {
		current = current.next
	}
	current.next = nil
	l.tail = current

}

// Append adds a new entry at the end of the list. If the list exceeds maxSize,
// the first entry is automatically removed.
func (l *List) Append(entry any) {
	if l.maxSize == 0 {
		return
	}

	newNode := &node{value: entry}

	if l.head == nil {
		l.head = newNode
		l.tail = newNode
		l.size = 1
		return
	}

	l.tail.next = newNode
	l.tail = newNode

	if l.size < l.maxSize {
		l.size++
	} else {
		l.head = l.head.next
	}
}

// Get returns the entry at the specified index.
// Index 0 is the oldest entry, Size()-1 is the newest.
func (l *List) Get(index int) any {
	if index < 0 || index >= l.size {
		return nil
	}

	current := l.head
	for i := 0; i < index; i++ {
		current = current.next
	}
	return current.value
}

// Size returns the current number of entries in the list
func (l *List) Size() int {
	return l.size
}

// MaxSize returns the maximum size configured for this list
func (l *List) MaxSize() int {
	return l.maxSize
}

// Entries returns all current entries as a slice
func (l *List) Entries() []any {
	entries := make([]any, l.size)
	current := l.head
	for i := 0; i < l.size; i++ {
		entries[i] = current.value
		current = current.next
	}
	return entries
}

// Iterator returns a function that can be used to iterate over the entries
// from oldest to newest. Returns nil when there are no more entries.
func (l *List) Iterator() func() any {
	current := l.head
	return func() any {
		if current == nil {
			return nil
		}
		value := current.value
		current = current.next
		return value
	}
}

// Latest returns the most recent entry.
// Returns nil if the list is empty.
func (l *List) Latest() any {
	if l.tail == nil {
		return nil
	}
	return l.tail.value
}

// SetMaxSize updates the maximum size of the list.
// If the new maxSize is smaller than the current size,
// the oldest entries are removed to fit the new size.
func (l *List) SetMaxSize(maxSize int) {
	if maxSize < 0 {
		maxSize = 0
	}

	// If new maxSize is smaller than current size,
	// remove oldest entries until we fit
	if maxSize < l.size {
		// Special case: if new maxSize is 0, clear the list
		if maxSize == 0 {
			l.head = nil
			l.tail = nil
			l.size = 0
		} else {
			// Keep the newest entries by moving head forward
			diff := l.size - maxSize
			for i := 0; i < diff; i++ {
				l.head = l.head.next
			}
			l.size = maxSize
		}
	}

	l.maxSize = maxSize
}

// Delete removes the element at the specified index.
// Returns true if an element was removed, false if the index was invalid.
func (l *List) Delete(index int) bool {
	if index < 0 || index >= l.size {
		return false
	}

	// Special case: deleting the only element
	if l.size == 1 {
		l.head = nil
		l.tail = nil
		l.size = 0
		return true
	}

	// Special case: deleting first element
	if index == 0 {
		l.head = l.head.next
		l.size--
		return true
	}

	// Find the node before the one to delete
	current := l.head
	for i := 0; i < index-1; i++ {
		current = current.next
	}

	// Special case: deleting last element
	if index == l.size-1 {
		l.tail = current
		current.next = nil
	} else {
		current.next = current.next.next
	}

	l.size--
	return true
}

// Package fp provides functional programming utilities for Gno, enabling
// transformations, filtering, and other operations on slices of any.
//
// Example of chaining operations:
//
//	numbers := []any{1, 2, 3, 4, 5, 6}
//
//	// Define predicates, mappers and reducers
//	isEven := func(v any) bool { return v.(int)%2 == 0 }
//	double := func(v any) any { return v.(int) * 2 }
//	sum := func(a, b any) any { return a.(int) + b.(int) }
//
//	// Chain operations: filter even numbers, double them, then sum
//	evenNums := Filter(numbers, isEven)        // [2, 4, 6]
//	doubled := Map(evenNums, double)           // [4, 8, 12]
//	result := Reduce(doubled, sum, 0)          // 24
//
//	// Alternative: group by even/odd, then get even numbers
//	byMod2 := func(v any) any { return v.(int) % 2 }
//	grouped := GroupBy(numbers, byMod2)        // {0: [2,4,6], 1: [1,3,5]}
//	evens := grouped[0]                        // [2,4,6]
package fp

// Mapper is a function type that maps an element to another element.
type Mapper func(any) any

// Predicate is a function type that evaluates a condition on an element.
type Predicate func(any) bool

// Reducer is a function type that reduces two elements to a single value.
type Reducer func(any, any) any

// Filter filters elements from the slice that satisfy the given predicate.
//
// Example:
//
//	numbers := []any{-1, 0, 1, 2}
//	isPositive := func(v any) bool { return v.(int) > 0 }
//	result := Filter(numbers, isPositive) // [1, 2]
func Filter(values []any, fn Predicate) []any {
	result := []any{}
	for _, v := range values {
		if fn(v) {
			result = append(result, v)
		}
	}
	return result
}

// Map applies a function to each element in the slice.
//
// Example:
//
//	numbers := []any{1, 2, 3}
//	toString := func(v any) any { return fmt.Sprintf("%d", v) }
//	result := Map(numbers, toString) // ["1", "2", "3"]
func Map(values []any, fn Mapper) []any {
	result := make([]any, len(values))
	for i, v := range values {
		result[i] = fn(v)
	}
	return result
}

// Reduce reduces a slice to a single value by applying a function.
//
// Example:
//
//	numbers := []any{1, 2, 3, 4}
//	sum := func(a, b any) any { return a.(int) + b.(int) }
//	result := Reduce(numbers, sum, 0) // 10
func Reduce(values []any, fn Reducer, initial any) any {
	acc := initial
	for _, v := range values {
		acc = fn(acc, v)
	}
	return acc
}

// FlatMap maps each element to a collection and flattens the results.
//
// Example:
//
//	words := []any{"hello", "world"}
//	split := func(v any) any {
//	    chars := []any{}
//	    for _, c := range v.(string) {
//	        chars = append(chars, string(c))
//	    }
//	    return chars
//	}
//	result := FlatMap(words, split) // ["h","e","l","l","o","w","o","r","l","d"]
func FlatMap(values []any, fn Mapper) []any {
	result := []any{}
	for _, v := range values {
		inner := fn(v).([]any)
		result = append(result, inner...)
	}
	return result
}

// All returns true if all elements satisfy the predicate.
//
// Example:
//
//	numbers := []any{2, 4, 6, 8}
//	isEven := func(v any) bool { return v.(int)%2 == 0 }
//	result := All(numbers, isEven) // true
func All(values []any, fn Predicate) bool {
	for _, v := range values {
		if !fn(v) {
			return false
		}
	}
	return true
}

// Any returns true if at least one element satisfies the predicate.
//
// Example:
//
//	numbers := []any{1, 3, 4, 7}
//	isEven := func(v any) bool { return v.(int)%2 == 0 }
//	result := Any(numbers, isEven) // true (4 is even)
func Any(values []any, fn Predicate) bool {
	for _, v := range values {
		if fn(v) {
			return true
		}
	}
	return false
}

// None returns true if no elements satisfy the predicate.
//
// Example:
//
//	numbers := []any{1, 3, 5, 7}
//	isEven := func(v any) bool { return v.(int)%2 == 0 }
//	result := None(numbers, isEven) // true (no even numbers)
func None(values []any, fn Predicate) bool {
	for _, v := range values {
		if fn(v) {
			return false
		}
	}
	return true
}

// Chunk splits a slice into chunks of the given size.
//
// Example:
//
//	numbers := []any{1, 2, 3, 4, 5}
//	result := Chunk(numbers, 2) // [[1,2], [3,4], [5]]
func Chunk(values []any, size int) [][]any {
	if size <= 0 {
		return nil
	}
	var chunks [][]any
	for i := 0; i < len(values); i += size {
		end := i + size
		if end > len(values) {
			end = len(values)
		}
		chunks = append(chunks, values[i:end])
	}
	return chunks
}

// Find returns the first element that satisfies the predicate and a boolean indicating if an element was found.
//
// Example:
//
//	numbers := []any{1, 2, 3, 4}
//	isEven := func(v any) bool { return v.(int)%2 == 0 }
//	result, found := Find(numbers, isEven) // 2, true
func Find(values []any, fn Predicate) (any, bool) {
	for _, v := range values {
		if fn(v) {
			return v, true
		}
	}
	return nil, false
}

// Reverse reverses the order of elements in a slice.
//
// Example:
//
//	numbers := []any{1, 2, 3}
//	result := Reverse(numbers) // [3, 2, 1]
func Reverse(values []any) []any {
	result := make([]any, len(values))
	for i, v := range values {
		result[len(values)-1-i] = v
	}
	return result
}

// Zip combines two slices into a slice of pairs. If the slices have different lengths,
// extra elements from the longer slice are ignored.
//
// Example:
//
//	a := []any{1, 2, 3}
//	b := []any{"a", "b", "c"}
//	result := Zip(a, b) // [[1,"a"], [2,"b"], [3,"c"]]
func Zip(a, b []any) [][2]any {
	length := min(len(a), len(b))
	result := make([][2]any, length)
	for i := 0; i < length; i++ {
		result[i] = [2]any{a[i], b[i]}
	}
	return result
}

// Unzip splits a slice of pairs into two separate slices.
//
// Example:
//
//	pairs := [][2]any{{1,"a"}, {2,"b"}, {3,"c"}}
//	numbers, letters := Unzip(pairs) // [1,2,3], ["a","b","c"]
func Unzip(pairs [][2]any) ([]any, []any) {
	a := make([]any, len(pairs))
	b := make([]any, len(pairs))
	for i, pair := range pairs {
		a[i] = pair[0]
		b[i] = pair[1]
	}
	return a, b
}

// GroupBy groups elements based on a key returned by a Mapper.
//
// Example:
//
//	numbers := []any{1, 2, 3, 4, 5, 6}
//	byMod3 := func(v any) any { return v.(int) % 3 }
//	result := GroupBy(numbers, byMod3) // {0: [3,6], 1: [1,4], 2: [2,5]}
func GroupBy(values []any, fn Mapper) map[any][]any {
	result := make(map[any][]any)
	for _, v := range values {
		key := fn(v)
		result[key] = append(result[key], v)
	}
	return result
}

// Flatten flattens a slice of slices into a single slice.
//
// Example:
//
//	nested := [][]any{{1,2}, {3,4}, {5}}
//	result := Flatten(nested) // [1,2,3,4,5]
func Flatten(values [][]any) []any {
	result := []any{}
	for _, v := range values {
		result = append(result, v...)
	}
	return result
}

// Helper functions
func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

// Package greet is a tiny pure package used as a canary: it proves that
// versioned cross-package resolution (gno.land/p/moul/greet/v1) works in the
// workspace and in CI. Replace or remove it once real packages land.
package greet

import "strings"

// Greet returns a friendly greeting for name (defaults to "world").
func Greet(name string) string {
	name = strings.TrimSpace(name)
	if name == "" {
		name = "world"
	}
	return "Hello, " + name + "!"
}

// Package md provides helper functions for generating Markdown content programmatically.
//
// It includes utilities for text formatting, creating lists, blockquotes, code blocks,
// links, images, and more.
//
// Highlights:
// - Supports basic Markdown syntax such as bold, italic, strikethrough, headers, and lists.
// - Manages multiline support in lists (e.g., bullet, ordered, and todo lists).
// - Includes advanced helpers like inline images with links and nested list prefixes.
//
// For a comprehensive example of how to use these helpers, see:
// https://gno.land/r/docs/moul_md
//
// # Sanitization contract
//
// Some helpers in this package sanitize their user-derived arguments
// INTERNALLY (via p/nt/markdown/sanitize/v0). When using these, pass
// raw user input — do NOT pre-wrap with sanitize.*, or you will
// double-wrap (the escapers are not idempotent and double-wrap is a
// bug):
//
//	Link, UserLink, Image, InlineImageWithLink, FootnoteDefinition,
//	LinkReferenceDefinition, CollapsibleSection (title only),
//	InlineCode, CodeBlock, LanguageCodeBlock, Blockquote
//
// The other helpers DO NOT sanitize — they are pure builders that
// wrap their input in markdown chrome. User-derived input reaches
// the output unmodified, so callers MUST wrap with sanitize.* at the
// call site:
//
//	Bold, Italic, Strikethrough, H1-H6, BulletList, BulletItem,
//	OrderedList, TodoList, TodoItem, Nested, Paragraph, Columns,
//	ColumnsN, HorizontalRule
//
// Examples:
//
//	// Sanitizing helper — pass raw:
//	out += md.Link(post.Title, post.URL)                                 // good
//	out += md.Link(sanitize.InlineText(post.Title), sanitize.URL(post.URL)) // BAD: double-wrap
//
//	// Non-sanitizing helper — wrap once:
//	out += md.H2(sanitize.InlineText(post.Title))                        // good
//	out += md.H2(post.Title)                                             // BAD: raw user input
//	out += md.H2(sanitize.InlineText(sanitize.InlineText(post.Title)))   // BAD: double-wrap
//
// Composition: outputs of sanitizing helpers are safe markdown chrome
// and can be embedded inside non-sanitizing helpers freely:
//
//	out += md.H2(md.Link(post.Title, post.URL))   // good — H2 doesn't re-escape Link's output
//
// The reverse is unsafe: do NOT embed a non-sanitizing helper's
// markdown chrome inside a sanitizing helper's arg, or the inner
// markdown gets re-escaped:
//
//	out += md.Link(md.Bold(post.Title), post.URL) // BAD: Link's internal sanitize
//	                                              // escapes the ** chars from md.Bold
package md

import (
	"strconv"
	"strings"

	"gno.land/p/nt/markdown/sanitize/v0"
)

// Bold returns bold text for markdown.
// Example: Bold("foo") => "**foo**"
func Bold(text string) string {
	return "**" + text + "**"
}

// Italic returns italicized text for markdown.
// Example: Italic("foo") => "*foo*"
func Italic(text string) string {
	return "*" + text + "*"
}

// Strikethrough returns strikethrough text for markdown.
// Example: Strikethrough("foo") => "~~foo~~"
func Strikethrough(text string) string {
	return "~~" + text + "~~"
}

// H1 returns a level 1 header for markdown.
// Example: H1("foo") => "# foo\n"
func H1(text string) string {
	return "# " + text + "\n"
}

// H2 returns a level 2 header for markdown.
// Example: H2("foo") => "## foo\n"
func H2(text string) string {
	return "## " + text + "\n"
}

// H3 returns a level 3 header for markdown.
// Example: H3("foo") => "### foo\n"
func H3(text string) string {
	return "### " + text + "\n"
}

// H4 returns a level 4 header for markdown.
// Example: H4("foo") => "#### foo\n"
func H4(text string) string {
	return "#### " + text + "\n"
}

// H5 returns a level 5 header for markdown.
// Example: H5("foo") => "##### foo\n"
func H5(text string) string {
	return "##### " + text + "\n"
}

// H6 returns a level 6 header for markdown.
// Example: H6("foo") => "###### foo\n"
func H6(text string) string {
	return "###### " + text + "\n"
}

// BulletList returns a bullet list for markdown.
// Example: BulletList([]string{"foo", "bar"}) => "- foo\n- bar\n"
func BulletList(items []string) string {
	var sb strings.Builder
	for _, item := range items {
		sb.WriteString(BulletItem(item))
	}
	return sb.String()
}

// BulletItem returns a bullet item for markdown.
// Example: BulletItem("foo") => "- foo\n"
func BulletItem(item string) string {
	var sb strings.Builder
	lines := strings.Split(item, "\n")
	sb.WriteString("- " + lines[0] + "\n")
	for _, line := range lines[1:] {
		sb.WriteString("  " + line + "\n")
	}
	return sb.String()
}

// OrderedList returns an ordered list for markdown.
// Example: OrderedList([]string{"foo", "bar"}) => "1. foo\n2. bar\n"
func OrderedList(items []string) string {
	var sb strings.Builder
	for i, item := range items {
		lines := strings.Split(item, "\n")
		sb.WriteString(strconv.Itoa(i+1) + ". " + lines[0] + "\n")
		for _, line := range lines[1:] {
			sb.WriteString("   " + line + "\n")
		}
	}
	return sb.String()
}

// TodoList returns a list of todo items with checkboxes for markdown.
// Example: TodoList([]string{"foo", "bar\nmore bar"}, []bool{true, false}) => "- [x] foo\n- [ ] bar\n  more bar\n"
func TodoList(items []string, done []bool) string {
	var sb strings.Builder
	for i, item := range items {
		sb.WriteString(TodoItem(item, done[i]))
	}
	return sb.String()
}

// TodoItem returns a todo item with checkbox for markdown.
// Example: TodoItem("foo", true) => "- [x] foo\n"
func TodoItem(item string, done bool) string {
	var sb strings.Builder
	checkbox := " "
	if done {
		checkbox = "x"
	}
	lines := strings.Split(item, "\n")
	sb.WriteString("- [" + checkbox + "] " + lines[0] + "\n")
	for _, line := range lines[1:] {
		sb.WriteString("  " + line + "\n")
	}
	return sb.String()
}

// Nested prefixes each line with a given prefix, enabling nested lists.
// Example: Nested("- foo\n- bar", "  ") => "  - foo\n  - bar\n"
func Nested(content, prefix string) string {
	lines := strings.Split(content, "\n")
	for i := range lines {
		if strings.TrimSpace(lines[i]) != "" {
			lines[i] = prefix + lines[i]
		}
	}
	return strings.Join(lines, "\n")
}

// Blockquote returns the text as a CommonMark blockquote.
// Example: Blockquote("foo\nbar") => "\n> foo\n> bar\n\n"
//
// Delegates to sanitize.Blockquote, which cleans the content (bidi-strip,
// CR/CRLF/U+2028/U+2029/NEL line-ending normalize, LRD strip, ref-link
// escape, block-marker escape, fence auto-close), line-prefixes each
// line with "> ", and wraps with "\n" / "\n\n" so the quote opens
// cleanly and cannot pull appended chrome into the quote via CM §5.2
// lazy continuation. Callers do NOT need to pre-wrap the input.
func Blockquote(text string) string {
	return sanitize.Blockquote(text)
}

// InlineCode wraps the given text as a CommonMark inline code span.
// Example: InlineCode("foo") => "`foo`"
//
// Delegates to sanitize.InlineCode, which cleans the input (bidi-strip,
// CR/CRLF + NEL + U+2028/U+2029 folded to single space, NUL→U+FFFD)
// and picks a backtick-run length that outscans any internal backticks.
// Callers do NOT need to pre-wrap the input.
func InlineCode(code string) string {
	return sanitize.InlineCode(code)
}

// CodeBlock creates a markdown code block.
// Example: CodeBlock("foo") => "```\nfoo\n```"
//
// Delegates to sanitize.CodeBlock, which cleans the content (bidi-strip,
// CR/CRLF normalize, NEL/U+2028/U+2029 fold, NUL→U+FFFD) and picks a
// fence wide enough to outscan any backticks in content. Callers do NOT
// need to pre-wrap content with another sanitize helper.
func CodeBlock(content string) string {
	return sanitize.CodeBlock(content)
}

// LanguageCodeBlock creates a markdown code block with language-specific syntax highlighting.
// Example: LanguageCodeBlock("go", "foo") => "```go\nfoo\n```"
//
// Delegates to sanitize.LanguageCodeBlock, which validates the language
// tag (charset ^[a-zA-Z0-9_+-]{1,32}$, falling back to a tagless fence
// if invalid) and cleans the content as CodeBlock does. Callers do NOT
// need to pre-wrap either argument.
func LanguageCodeBlock(language, content string) string {
	return sanitize.LanguageCodeBlock(language, content)
}

// HorizontalRule returns a horizontal rule for markdown.
// Example: HorizontalRule() => "---\n"
func HorizontalRule() string {
	return "---\n"
}

// Link returns a hyperlink for markdown.
// Example: Link("foo", "http://example.com") => "[foo](http://example.com)"
//
// The text and url args are sanitized internally — text via
// sanitize.InlineText, url via sanitize.URL (allowlists http/https/
// mailto/relative/fragment; rejects javascript:, data:, blob:, etc.).
// Callers do NOT need to pre-wrap either argument; double-wrapping is
// a bug (the inline-text escaper is non-idempotent).
//
// If the URL fails the scheme allowlist, the href is rendered empty —
// the link becomes inert rather than carrying a malicious destination.
func Link(text, url string) string {
	return "[" + sanitize.InlineText(text) + "](" + sanitize.URL(url) + ")"
}

// UserLink returns a user profile link for markdown.
// Example: UserLink("moul") => "[@moul](/u/moul)"
// Example: UserLink("g1blah...") => "[g1blah...](/u/g1blah...)"
//
// Validates the user identifier — if it matches the gno bech32 address
// pattern (g1...), produces an address-style link; otherwise tries the
// r/sys/users-charset username and produces an @-style link. Returns
// "" if the identifier matches neither — callers should treat "" as
// "skip the user mention" rather than emit a broken link.
func UserLink(user string) string {
	if addr := sanitize.BechString(user, "g"); addr != "" {
		return "[" + addr + "](/u/" + addr + ")"
	}
	if name := sanitize.UserName(user); name != "" {
		return "[@" + name + "](/u/" + name + ")"
	}
	return ""
}

// InlineImageWithLink creates an inline image wrapped in a hyperlink for markdown.
// Example: InlineImageWithLink("alt text", "image-url", "link-url") => "[![alt text](image-url)](link-url)"
//
// altText and imageUrl are sanitized via Image (sanitize.InlineText +
// sanitize.ImageURL); linkUrl is sanitized via sanitize.URL. Callers
// do NOT need to pre-wrap any argument.
func InlineImageWithLink(altText, imageUrl, linkUrl string) string {
	return "[" + Image(altText, imageUrl) + "](" + sanitize.URL(linkUrl) + ")"
}

// Image returns an image for markdown.
// Example: Image("foo", "http://example.com") => "![foo](http://example.com)"
//
// altText is sanitized via sanitize.InlineText, url via
// sanitize.ImageURL (allowlists http/https/relative + data:image/*;
// rejects mailto:, javascript:, data:text/html, etc.). Callers do NOT
// need to pre-wrap either argument.
func Image(altText, url string) string {
	return "![" + sanitize.InlineText(altText) + "](" + sanitize.ImageURL(url) + ")"
}

// FootnoteDefinition emits a GFM footnote definition — `[^name]: body` —
// for a footnote that is referenced elsewhere in the document by
// `[^name]`.
//
// Example: FootnoteDefinition("note1", "Long form of the citation.")
// renders as:
//
//	[^note1]:
//	    Long form of the citation.
//
// The `name` is validated as a FootnoteLabel (^[A-Za-z0-9_-]{1,64}$);
// `text` is user-supplied multi-paragraph prose, sanitized via Block.
// An invalid name or empty body returns "".
//
// Delegates to sanitize.FootnoteDefinition. Callers do NOT need to
// pre-wrap either argument.
func FootnoteDefinition(name, text string) string {
	return sanitize.FootnoteDefinition(name, text)
}

// LinkReferenceDefinition emits a CommonMark link reference definition
// (CM §4.7) — `[label]: url "title"` — for a reference link that is
// invoked elsewhere by `[text][label]` or by the shortcut form
// `[label]`.
//
// Example: LinkReferenceDefinition("r/docs/help", "/r/docs/help", "")
// renders as:
//
//	[r/docs/help]: /r/docs/help
//
// The `label` is validated as a FootnoteLabel (^[A-Za-z0-9_-]{1,64}$);
// `url` is sanitized via URL (allowlist); `title` is sanitized via
// LinkTitle. An invalid label or rejected URL returns "".
//
// Realms should choose a namespaced label using dashes
// (e.g. `r-myrealm-help`) so that shortcut-reference invocations from
// user content can't collide with bare words a user is likely to write.
// `/` is not in the FootnoteLabel charset.
//
// Delegates to sanitize.LinkReferenceDefinition. Callers do NOT need to
// pre-wrap any argument.
func LinkReferenceDefinition(label, url, title string) string {
	return sanitize.LinkReferenceDefinition(label, url, title)
}

// Paragraph wraps the given text in a Markdown paragraph.
// Example: Paragraph("foo") => "foo\n"
func Paragraph(content string) string {
	return content + "\n\n"
}

// CollapsibleSection creates a collapsible section for markdown using
// HTML <details> and <summary> tags.
// Example:
// CollapsibleSection("Click to expand", "Hidden content")
// =>
// <details><summary>Click to expand</summary>
//
// Hidden content
// </details>
//
// The title argument is sanitized via sanitize.HTMLEscape (it lands in
// an HTML element body inside <summary>, not a markdown context — so
// HTML entity escaping is the correct policy, not markdown backslash
// escaping). The content argument is passed through unchanged because
// <details> with a blank-line-separated body allows markdown inside
// (CM §4.6); callers must pre-wrap content with sanitize.Block if it
// derives from user input.
func CollapsibleSection(title, content string) string {
	return "<details><summary>" + sanitize.HTMLEscape(title) + "</summary>\n\n" + content + "\n</details>\n"
}

// EscapeURL escapes characters in a URL for use in markdown link syntax.
//
// Deprecated: use sanitize.URL (for link href) or sanitize.ImageURL
// (for image src) directly. EscapeURL previously only percent-encoded
// ( and ) and did not validate the URL scheme — a security footgun
// (EscapeURL("javascript:alert(1)") returned a working XSS payload).
// It now delegates to sanitize.URL, which allowlists schemes (rejects
// javascript:, data:text/html, vbscript:, blob:, etc.) and
// percent-encodes all unsafe bytes (including the ( ) this function
// handled). The other helpers in this package (Link, UserLink, Image,
// InlineImageWithLink) sanitize their URL args internally now, so you
// rarely need to call any URL-escape helper directly.
//
// Behavior change vs. the original implementation: invalid schemes
// now return "" instead of passing through with ( ) escaped. Non-ASCII
// bytes get percent-encoded to standard RFC 3986 wire form instead of
// passing through as raw UTF-8.
func EscapeURL(url string) string {
	return sanitize.URL(url)
}

// EscapeText escapes special Markdown characters in regular text for
// use in inline contexts.
//
// Deprecated: use sanitize.InlineText directly. EscapeText was
// INCOMPLETE — it missed \, #, <, & and did not strip bidi/zero-width
// characters, replace NUL with U+FFFD, or normalize line endings.
// User input could inject backslash escapes (\* cancels neighboring
// escapes), autolinks (<https://x>), raw HTML (<script>), HTML entity
// references (&amp;), and bidi spoofing (RLO before an address). It
// now delegates to sanitize.InlineText. The other helpers in this
// package (Link, UserLink, Image, InlineImageWithLink, CollapsibleSection)
// sanitize their text args internally now, so you rarely need to call
// any inline-text-escape helper directly.
//
// Behavior change vs. the original implementation: \, #, <, & are now
// escaped; | is no longer escaped (the original was over-escaping —
// outside GFM table-cell context, | is markdown-inert; for table
// cells use sanitize.TableCell which adds the | escape on top of the
// inline-text set). Bidi controls are stripped, NUL becomes U+FFFD,
// and line endings normalize.
func EscapeText(text string) string {
	return sanitize.InlineText(text)
}

// Columns returns a formatted row of columns using the Gno syntax.
// If you want a specific number of columns per row (<=4), use ColumnsN.
// Check /r/docs/markdown#columns for more info.
// If padded=true & the final <gno-columns> tag is missing column content, an empty
// column element will be placed to keep the cols per row constant.
// Padding works only with colsPerRow > 0.
//
// Example:
//
//	Columns([]string{"A", "B"}, false)
//	// Returns:
//	// <gno-columns>
//	// A
//	// <gno-columns-sep>
//	// B
//	// </gno-columns>
func Columns(contentByColumn []string, padded bool) string {
	if len(contentByColumn) == 0 {
		return ""
	}
	maxCols := 4
	if padded && len(contentByColumn)%maxCols != 0 {
		missing := maxCols - len(contentByColumn)%maxCols
		contentByColumn = append(contentByColumn, make([]string, missing)...)
	}

	var sb strings.Builder
	sb.WriteString("<gno-columns>\n")

	for i, column := range contentByColumn {
		if i > 0 {
			sb.WriteString("<gno-columns-sep>\n")
		}
		sb.WriteString(column + "\n")
	}

	sb.WriteString("</gno-columns>\n")
	return sb.String()
}

const maxColumnsPerRow = 4

// ColumnsN splits content into multiple rows of N columns each and formats them.
// If colsPerRow <= 0, all items are placed in one <gno-columns> block.
// If padded=true & the final <gno-columns> tag is missing column content, an empty
// column element will be placed to keep the cols per row constant.
// Padding works only with colsPerRow > 0.
// Note: On standard-size screens, gnoweb handles a max of 4 cols per row.
//
// Example:
//
//	ColumnsN([]string{"A", "B", "C"}, 2, false)
//	// Returns:
//	// <gno-columns>
//	// A
//	// <gno-columns-sep>
//	// B
//	// </gno-columns>
//	// <gno-columns>
//	// C
//	// </gno-columns>
func ColumnsN(content []string, colsPerRow int, padded bool) string {
	if len(content) == 0 {
		return ""
	}
	if colsPerRow <= 0 {
		return Columns(content, padded)
	}

	var sb strings.Builder
	// Case 2: Multiple blocks with max 4 columns
	for i := 0; i < len(content); i += colsPerRow {
		end := i + colsPerRow
		if end > len(content) {
			end = len(content)
		}
		row := content[i:end]

		// Add padding if needed
		if padded && len(row) < colsPerRow {
			row = append(row, make([]string, colsPerRow-len(row))...)
		}

		sb.WriteString(Columns(row, false))
	}
	return sb.String()
}

// Package mdlist is a proof-of-concept for composable UIs patterns.
//
// It allows specifying a data source and then dynamically rendering it as
// a list or a grid.
package mdlist

import (
	"strings"

	"gno.land/p/moul/md/v1"
)

// XXX: configurable length UL
// XXX: moul/pager.Pager-powered auto mdlist
// XXX: func (l List) Render(path string) string {
// XXX: add .Table()

type Entries []Entry

type Entry struct {
	// Title is the title of the entry. Required.
	Title string
	// Body is the body of the entry. Required.
	Body string
	// Link is the URL of the entry. Optional.
	Link string
	// Links is a list of additional URLs of the entry. Optional.
	Links []string
}

// BulletList returns entries as a markdown bullet list without truncation.
func (l Entries) BulletList() string {
	return l.BulletListTruncated(-1, -1)
}

// BulletListTruncated returns entries as a markdown bullet list with truncation.
func (l Entries) BulletListTruncated(titleMaxLength, bodyMaxLength int) string {
	items := make([]string, len(l))
	for i, entry := range l {
		title := truncateText(entry.Title, titleMaxLength, false)
		if entry.Link != "" {
			title = md.Link(title, entry.Link)
		}
		body := truncateText(entry.Body, bodyMaxLength, true)
		links := strings.Join(entry.Links, " ")
		item := md.Bold(title) + ": " + md.Italic(body) + " " + links
		items[i] = strings.TrimSpace(item)
	}
	return md.BulletList(items)
}

// NumberedList returns entries as a markdown numbered list without truncation.
func (l Entries) NumberedList() string {
	return l.NumberedListTruncated(-1, -1)
}

// NumberedListTruncated returns entries as a markdown numbered list with truncation.
func (l Entries) NumberedListTruncated(titleMaxLength, bodyMaxLength int) string {
	items := make([]string, len(l))
	for i, entry := range l {
		title := truncateText(entry.Title, titleMaxLength, false)
		if entry.Link != "" {
			title = md.Link(title, entry.Link)
		}
		body := truncateText(entry.Body, bodyMaxLength, true)
		links := strings.Join(entry.Links, " ")
		item := md.Bold(title) + ": " + md.Italic(body) + " " + links
		items[i] = strings.TrimSpace(item)
	}
	return md.OrderedList(items)
}

// Paragraphs returns entries as simple paragraphs with bold titles.
func (l Entries) Paragraphs() string {
	paragraphs := make([]string, len(l))
	for i, entry := range l {
		title := entry.Title
		if entry.Link != "" {
			title = md.Link(title, entry.Link)
		}
		paragraph := md.Bold(title) + ". " + entry.Body
		if len(entry.Links) > 0 {
			paragraph += " " + strings.Join(entry.Links, " ")
		}
		paragraphs[i] = paragraph
	}
	return strings.Join(paragraphs, "\n\n")
}

func (l Entries) Columns() string {
	columns := make([]string, len(l))
	for i, entry := range l {
		title := entry.Title
		if entry.Link != "" {
			title = md.Link(title, entry.Link)
		}
		body := entry.Body
		links := strings.Join(entry.Links, " ")
		columns[i] = md.H2(title) + md.Paragraph(body) + md.Paragraph(links)
	}
	return md.Columns(columns, false)
}

func truncateText(content string, maxLength int, withNewLines bool) string {
	// If maxLength is -1, don't truncate
	if maxLength < 0 {
		if !withNewLines {
			content = strings.ReplaceAll(content, "\n", " ")
		}
		return content
	}
	if !withNewLines {
		content = strings.ReplaceAll(content, "\n", " ")
	}
	if len(content) > maxLength {
		return content[:maxLength-3] + "..."
	}
	return content
}

// Package mdtable provides a simple way to create Markdown tables.
//
// Example usage:
//
//	import "gno.land/p/moul/mdtable/v1"
//
//	func Render(path string) string {
//	    table := mdtable.Table{
//	        Headers: []string{"ID", "Title", "Status", "Date"},
//	    }
//	    table.Append([]string{"#1", "Add a new validator", "succeed", "2024-01-01"})
//	    table.Append([]string{"#2", "Change parameter", "timed out", "2024-01-02"})
//	    return table.String()
//	}
//
// Output:
//
//	| ID | Title | Status | Date |
//	| --- | --- | --- | --- |
//	| #1 | Add a new validator | succeed | 2024-01-01 |
//	| #2 | Change parameter | timed out | 2024-01-02 |
package mdtable

import (
	"strings"
)

type Table struct {
	Headers []string
	Rows    [][]string
	// XXX: optional headers alignment.
}

func (t *Table) Append(row []string) {
	t.Rows = append(t.Rows, row)
}

func (t Table) String() string {
	// XXX: switch to using text/tabwriter when porting to Gno to support
	// better-formatted raw Markdown output.

	if len(t.Headers) == 0 && len(t.Rows) == 0 {
		return ""
	}

	var sb strings.Builder

	if len(t.Headers) == 0 {
		t.Headers = make([]string, len(t.Rows[0]))
	}

	// Print header.
	sb.WriteString("| " + strings.Join(t.Headers, " | ") + " |\n")
	sb.WriteString("|" + strings.Repeat(" --- |", len(t.Headers)) + "\n")

	// Print rows.
	for _, row := range t.Rows {
		escapedRow := make([]string, len(row))
		for i, cell := range row {
			escapedRow[i] = strings.ReplaceAll(cell, "|", "&#124;") // Escape pipe characters.
		}
		sb.WriteString("| " + strings.Join(escapedRow, " | ") + " |\n")
	}

	return sb.String()
}

// Package memo provides a simple memoization utility to cache function results.
//
// The package offers a Memoizer type that can cache function results based on keys,
// with optional validation of cached values. This is useful for expensive computations
// that need to be cached and potentially invalidated based on custom conditions.
//
// /!\ Important Warning for Gno Usage:
// In Gno, storage updates only persist during transactions. This means:
//   - Cache entries created during queries will NOT persist
//   - Creating cache entries during queries will actually decrease performance
//     as it wastes resources trying to save data that won't be saved
//
// Best Practices:
// - Use this pattern in transaction-driven contexts rather than query/render scenarios
// - Consider controlled cache updates, e.g., by specific accounts (like oracles)
// - Ideal for cases where cache updates happen every N blocks or on specific events
// - Carefully evaluate if caching will actually improve performance in your use case
//
// Basic usage example:
//
//	m := memo.New()
//
//	// Cache expensive computation
//	result := m.Memoize("key", func() any {
//	    // expensive operation
//	    return "computed-value"
//	})
//
//	// Subsequent calls with same key return cached result
//	result = m.Memoize("key", func() any {
//	    // function won't be called, cached value is returned
//	    return "computed-value"
//	})
//
// Example with validation:
//
//	type TimestampedValue struct {
//	    Value     string
//	    Timestamp time.Time
//	}
//
//	m := memo.New()
//
//	// Cache value with timestamp
//	result := m.MemoizeWithValidator(
//	    "key",
//	    func() any {
//	        return TimestampedValue{
//	            Value:     "data",
//	            Timestamp: time.Now(),
//	        }
//	    },
//	    func(cached any) bool {
//	        // Validate that the cached value is not older than 1 hour
//	        if tv, ok := cached.(TimestampedValue); ok {
//	            return time.Since(tv.Timestamp) < time.Hour
//	        }
//	        return false
//	    },
//	)
package memo

import (
	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
)

// keyString derives a stable string key from an arbitrary value. Keys are
// compared by their string representation, mirroring the previous ordering
// behavior.
func keyString(key any) string {
	return ufmt.Sprintf("%v", key)
}

// Memoizer is a structure to handle memoization of function results.
type Memoizer struct {
	cache *avl.Tree
}

// New creates a new Memoizer instance.
func New() *Memoizer {
	return &Memoizer{
		cache: avl.NewTree(),
	}
}

// Memoize ensures the result of the given function is cached for the specified key.
func (m *Memoizer) Memoize(key any, fn func() any) any {
	k := keyString(key)
	if m.cache.Has(k) {
		return m.cache.Get(k)
	}

	value := fn()
	m.cache.Set(k, value)
	return value
}

// MemoizeWithValidator ensures the result is cached and valid according to the validator function.
func (m *Memoizer) MemoizeWithValidator(key any, fn func() any, isValid func(any) bool) any {
	k := keyString(key)
	if m.cache.Has(k) {
		cached := m.cache.Get(k)
		if isValid(cached) {
			return cached
		}
	}

	value := fn()
	m.cache.Set(k, value)
	return value
}

// Invalidate removes the cached value for the specified key.
func (m *Memoizer) Invalidate(key any) {
	m.cache.Remove(keyString(key))
}

// Clear clears all cached values.
func (m *Memoizer) Clear() {
	m.cache = avl.NewTree()
}

// Size returns the number of items currently in the cache.
func (m *Memoizer) Size() int {
	return m.cache.Size()
}

// Package nestedpkg provides helpers for package-path based access control.
// It is useful for upgrade patterns relying on namespaces.
//
// SECURITY: every exported helper takes `rlm realm` and reads both
// `rlm.PkgPath()` and `rlm.Previous().PkgPath()` to make an
// authorization decision. To close Class-2 designation forgery (a
// hostile realm stashes a captured realm value and passes it back to
// spoof identity), every helper gates on `rlm.IsCurrent()` first. The
// Is* predicates return false on stale rlm (fail-closed); the Assert*
// helpers panic. See docs/resources/gno-security.md.
package nestedpkg

import "strings"

// IsCallerSubPath checks if the caller realm is located in a subfolder of the current realm.
func IsCallerSubPath(_ int, rlm realm) bool {
	if !rlm.IsCurrent() {
		return false
	}
	var (
		curPath  = rlm.PkgPath() + "/"
		prevPath = rlm.Previous().PkgPath() + "/"
	)
	return strings.HasPrefix(prevPath, curPath)
}

// AssertCallerIsSubPath panics if IsCallerSubPath returns false.
func AssertCallerIsSubPath(_ int, rlm realm) {
	if !rlm.IsCurrent() {
		panic("unauthorized: rlm is not the caller's live cur")
	}
	var (
		curPath  = rlm.PkgPath() + "/"
		prevPath = rlm.Previous().PkgPath() + "/"
	)
	if !strings.HasPrefix(prevPath, curPath) {
		panic("call restricted to nested packages. current realm is " + curPath + ", previous realm is " + prevPath)
	}
}

// IsCallerParentPath checks if the caller realm is located in a parent location of the current realm.
func IsCallerParentPath(_ int, rlm realm) bool {
	if !rlm.IsCurrent() {
		return false
	}
	var (
		curPath  = rlm.PkgPath() + "/"
		prevPath = rlm.Previous().PkgPath() + "/"
	)
	return strings.HasPrefix(curPath, prevPath)
}

// AssertCallerIsParentPath panics if IsCallerParentPath returns false.
func AssertCallerIsParentPath(_ int, rlm realm) {
	if !rlm.IsCurrent() {
		panic("unauthorized: rlm is not the caller's live cur")
	}
	var (
		curPath  = rlm.PkgPath() + "/"
		prevPath = rlm.Previous().PkgPath() + "/"
	)
	if !strings.HasPrefix(curPath, prevPath) {
		panic("call restricted to parent packages. current realm is " + curPath + ", previous realm is " + prevPath)
	}
}

// IsSameNamespace checks if the caller realm and the current realm are in the same namespace.
func IsSameNamespace(_ int, rlm realm) bool {
	if !rlm.IsCurrent() {
		return false
	}
	var (
		curNs  = nsFromPath(rlm.PkgPath()) + "/"
		prevNs = nsFromPath(rlm.Previous().PkgPath()) + "/"
	)
	return curNs == prevNs
}

// AssertIsSameNamespace panics if IsSameNamespace returns false.
func AssertIsSameNamespace(_ int, rlm realm) {
	if !rlm.IsCurrent() {
		panic("unauthorized: rlm is not the caller's live cur")
	}
	var (
		curNs  = nsFromPath(rlm.PkgPath()) + "/"
		prevNs = nsFromPath(rlm.Previous().PkgPath()) + "/"
	)
	if curNs != prevNs {
		panic("call restricted to packages from the same namespace. current realm is " + curNs + ", previous realm is " + prevNs)
	}
}

// nsFromPath extracts the namespace from a package path.
func nsFromPath(pkgpath string) string {
	parts := strings.Split(pkgpath, "/")

	// Specifically for gno.land, potential paths are in the form of DOMAIN/r/NAMESPACE/...
	// XXX: Consider extra checks.
	// XXX: Support non gno.land domains, where p/ and r/ won't be enforced.
	if len(parts) >= 3 {
		return parts[2]
	}
	return ""
}

